// Beallitasok es a letoltendo szezonok.
//
// A szezonkod YYZZ: a 2026/27-es szezon '2627'. Ket szezont toltunk be,
// mert a folyo szezon elejen meg alig van meccs (a modell kulonben
// 3 meccsbol probalna csapaterosseget becsulni).

const NOW = new Date();
const y = NOW.getUTCFullYear(), mo = NOW.getUTCMonth() + 1;
// a szezon augusztusban indul: januar-julius kozott meg az elozo evi szezonban vagyunk
const startYear = mo >= 8 ? y : y - 1;
const sc = yr => String(yr % 100).padStart(2, '0') + String((yr + 1) % 100).padStart(2, '0');
const SEASONS = [sc(startYear), sc(startYear - 1)];

const LEAGUES = [
  { code: 'E0',  api: 'soccer_epl',                 name: 'Premier League' },
  { code: 'SP1', api: 'soccer_spain_la_liga',       name: 'La Liga' },
  { code: 'D1',  api: 'soccer_germany_bundesliga',  name: 'Bundesliga' },
  { code: 'I1',  api: 'soccer_italy_serie_a',       name: 'Serie A' },
  { code: 'F1',  api: 'soccer_france_ligue_one',    name: 'Ligue 1' },
];

const CONFIG = {
  minOdds: 1.30,          // ez alatt nem kerul labkent a slate-re
  maxOdds: 15.0,
  maxHoursAhead: 96,      // ennyi oran belul kezdodo meccsek
  // A Tippmixpro nincs a The Odds API-ban (magyar allami monopol konyv), ezert
  // a piaci atlagbol becsuljuk. Meres: egy atlagos konyv 3.15%-kal kevesebbet
  // fizet a Pinnacle-nel, egy monopol konyv jellemzoen ennel is tobbet vag.
  // Par valos Tippmixpro odds osszevetese utan pontositsd ezt a szamot.
  tippmixHaircut: 0.045,
};

const out = [];
for (const lg of LEAGUES) {
  for (const s of SEASONS) {
    out.push({ json: {
      url: `https://www.football-data.co.uk/mmz4281/${s}/${lg.code}.csv`,
      league: lg.code, api: lg.api, league_name: lg.name, season: s,
      leagues: LEAGUES, config: CONFIG,
    }});
  }
}
return out;

// CSV feldolgozas + Dixon-Coles csapaterossegek.
// Ez a kod lokalisan tesztelve lett 1849 meccsen mielott ide kerult.

const XI = 0.0065;      // idobeli sulyozas: ~107 napos felezes
const SHRINK_K = 12;    // ennyi sulyozott meccsnel 50% a sajat adat
const XG_BLEND = 0.5;   // xG es valos gol keverese
const PRIOR_ATT = 0.92; // ujoncok atlag alatt teljesitenek
const PRIOR_DEF = 1.08;

function parseCsv(raw, league) {
  const text = String(raw).replace(/^\uFEFF/, '');
  const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
  if (lines.length < 2) return [];
  // fejlecnev szerinti indexeles: az oszlopsorrend szezononkent valtozik
  const head = lines[0].split(',').map(h => h.trim());
  const col = {};
  head.forEach((h, i) => { if (col[h] === undefined) col[h] = i; });
  for (const n of ['Date', 'HomeTeam', 'AwayTeam', 'FTHG', 'FTAG']) {
    if (col[n] === undefined) return [];
  }
  const hasXg = col['HxG'] !== undefined && col['AxG'] !== undefined;
  const out = [];
  for (let i = 1; i < lines.length; i++) {
    const f = lines[i].split(',');
    const home = (f[col['HomeTeam']] || '').trim();
    const away = (f[col['AwayTeam']] || '').trim();
    const fthg = f[col['FTHG']], ftag = f[col['FTAG']];
    if (!home || !away || fthg === undefined || fthg === '' || ftag === '') continue;
    const hg = Number(fthg), ag = Number(ftag);
    if (!Number.isFinite(hg) || !Number.isFinite(ag)) continue;
    // dd/mm/yyyy — NEM ISO, kezzel kell bontani
    const m = (f[col['Date']] || '').trim().match(/^(\d{2})\/(\d{2})\/(\d{2}|\d{4})$/);
    if (!m) continue;
    const yr = m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]);
    const date = new Date(Date.UTC(yr, Number(m[2]) - 1, Number(m[1])));
    if (isNaN(date.getTime())) continue;
    const row = { league, date: date.toISOString(), home, away, hg, ag, hxg: null, axg: null };
    if (hasXg) {
      const hx = Number(f[col['HxG']]), ax = Number(f[col['AxG']]);
      if (Number.isFinite(hx) && Number.isFinite(ax)) { row.hxg = hx; row.axg = ax; }
    }
    out.push(row);
  }
  return out;
}

// --- osszes CSV beolvasasa ---
let matches = [];
const fetchErrors = [];
let config = null, leagues = null;

for (const item of $input.all()) {
  const j = item.json;
  if (!config && j.config) { config = j.config; leagues = j.leagues; }
  const status = j.statusCode;
  const body = j.body !== undefined ? j.body : j.data;
  if (status && status !== 200) {
    fetchErrors.push(`${j.league || '?'} ${j.season || ''}: HTTP ${status}`);
    continue;
  }
  if (typeof body !== 'string' || body.length < 100) {
    fetchErrors.push(`${j.league || '?'} ${j.season || ''}: ures valasz`);
    continue;
  }
  const rows = parseCsv(body, j.league);
  if (!rows.length) fetchErrors.push(`${j.league} ${j.season}: 0 meccs`);
  matches = matches.concat(rows);
}

if (!config) { config = {}; leagues = []; }

// --- Dixon-Coles erossegek ---
const now = new Date();
const byLeague = {};
for (const m of matches) (byLeague[m.league] = byLeague[m.league] || []).push(m);

const ratings = {};
const leagueMeta = {};

for (const [league, rows] of Object.entries(byLeague)) {
  const enriched = rows.map(m => {
    const days = Math.max(0, (now - new Date(m.date)) / 86400000);
    const w = Math.exp(-XI * days);
    let hVal = m.hg, aVal = m.ag;
    if (m.hxg !== null && m.axg !== null) {
      hVal = XG_BLEND * m.hxg + (1 - XG_BLEND) * m.hg;
      aVal = XG_BLEND * m.axg + (1 - XG_BLEND) * m.ag;
    }
    return { ...m, w, hVal, aVal };
  }).filter(m => m.w > 1e-6);
  if (!enriched.length) continue;

  let sw = 0, shg = 0, sag = 0;
  for (const m of enriched) { sw += m.w; shg += m.w * m.hVal; sag += m.w * m.aVal; }
  const avgHome = shg / sw, avgAway = sag / sw;
  const leagueAvg = (avgHome + avgAway) / 2;
  const homeAdv = avgAway > 0 ? avgHome / avgAway : 1.3;
  leagueMeta[league] = { leagueAvg, homeAdv, matches: enriched.length };

  const t = {};
  const get = n => (t[n] = t[n] || { sf: 0, sa: 0, w: 0, games: 0 });
  for (const m of enriched) {
    const H = get(m.home), A = get(m.away);
    H.sf += m.w * (m.hVal / homeAdv); H.sa += m.w * m.aVal; H.w += m.w; H.games++;
    A.sf += m.w * m.aVal; A.sa += m.w * (m.hVal / homeAdv); A.w += m.w; A.games++;
  }
  for (const [team, s] of Object.entries(t)) {
    const k = s.w / (s.w + SHRINK_K);
    ratings[league + '|' + team] = {
      team, league,
      attack: k * ((s.sf / s.w) / leagueAvg) + (1 - k) * PRIOR_ATT,
      defence: k * ((s.sa / s.w) / leagueAvg) + (1 - k) * PRIOR_DEF,
      matches: s.games,
    };
  }
}

return [{ json: {
  ratings, leagueMeta, config, leagues,
  total_matches: matches.length,
  fetch_errors: fetchErrors,
  teams_rated: Object.keys(ratings).length,
}}];

// Ingyenes foci RSS-ek, kulcs nelkul. Ellenorizve: BBC 87 cikk, Guardian 60.
// A modellt tovabbvisszuk, hogy a lanc kesobbi node-jai elerjek.
const model = $json;
const FEEDS = [
  { url: 'https://feeds.bbci.co.uk/sport/football/rss.xml', source: 'BBC' },
  { url: 'https://www.theguardian.com/football/rss',        source: 'Guardian' },
];
return FEEDS.map(f => ({ json: { ...f, _model: model } }));

// RSS parse. A BBC CDATA-t hasznal a cimekhez, a Guardian nem — mindketto kell.
// A kimenet EGY item: a modell + a cikkek, hogy a lanc tovabb tudjon menni.

function parseRss(xml, source) {
  const out = [];
  const items = String(xml).split('<item>').slice(1);
  for (const raw of items) {
    const chunk = raw.split('</item>')[0];
    const pick = tag => {
      const cdata = new RegExp('<' + tag + '><!\\[CDATA\\[([\\s\\S]*?)\\]\\]></' + tag + '>').exec(chunk);
      if (cdata) return cdata[1].trim();
      const plain = new RegExp('<' + tag + '>([\\s\\S]*?)</' + tag + '>').exec(chunk);
      return plain ? plain[1].replace(/<[^>]*>/g, '').trim() : '';
    };
    const title = pick('title');
    if (!title) continue;
    out.push({
      source,
      title,
      description: pick('description').slice(0, 300),
      pubDate: pick('pubDate'),
    });
  }
  return out;
}

let model = null;
const articles = [];
const newsErrors = [];

for (const item of $input.all()) {
  const j = item.json;
  if (!model && j._model) model = j._model;
  const status = j.statusCode;
  const body = j.body !== undefined ? j.body : j.data;
  if (status && status !== 200) { newsErrors.push((j.source || '?') + ': HTTP ' + status); continue; }
  if (typeof body !== 'string' || body.length < 200) { newsErrors.push((j.source || '?') + ': ures valasz'); continue; }
  try {
    articles.push(...parseRss(body, j.source || '?'));
  } catch (e) {
    newsErrors.push((j.source || '?') + ': parse hiba');
  }
}

// A modell mezoit a legfelso szintre tesszuk, hogy a Fan Out Leagues valtozatlanul mukodjon.
const base = model || {};
return [{ json: { ...base, _articles: articles, _news_errors: newsErrors } }];

// A modell mellé most az odds kell. Ligankent egy kereses.
const m = $json;
return (m.leagues || []).map(lg => ({ json: {
  ...lg,
  _model: { ratings: m.ratings, leagueMeta: m.leagueMeta, config: m.config,
            total_matches: m.total_matches, fetch_errors: m.fetch_errors,
            teams_rated: m.teams_rated },
}}));

// A "Generate Legs" node kodja. MINDEN kimenetel labkent, harom piacon.

const MAX_GOALS = 10;
const RHO = -0.13;

function poissonPmf(k, lambda) {
  let logF = 0;
  for (let i = 2; i <= k; i++) logF += Math.log(i);
  return Math.exp(-lambda + k * Math.log(lambda) - logF);
}
function tau(hg, ag, lh, la, rho) {
  if (hg === 0 && ag === 0) return 1 - lh * la * rho;
  if (hg === 0 && ag === 1) return 1 + lh * rho;
  if (hg === 1 && ag === 0) return 1 + la * rho;
  if (hg === 1 && ag === 1) return 1 - rho;
  return 1;
}
function predict(hr, ar, leagueAvg, homeAdv) {
  const lh = hr.attack * ar.defence * leagueAvg * homeAdv;
  const la = ar.attack * hr.defence * leagueAvg;
  const grid = []; let total = 0;
  for (let h = 0; h <= MAX_GOALS; h++) {
    grid[h] = [];
    for (let a = 0; a <= MAX_GOALS; a++) {
      const p = poissonPmf(h, lh) * poissonPmf(a, la) * tau(h, a, lh, la, RHO);
      grid[h][a] = Math.max(0, p); total += grid[h][a];
    }
  }
  let home = 0, draw = 0, away = 0, over25 = 0, btts = 0;
  for (let h = 0; h <= MAX_GOALS; h++) for (let a = 0; a <= MAX_GOALS; a++) {
    const p = grid[h][a] / total;
    if (h > a) home += p; else if (h === a) draw += p; else away += p;
    if (h + a > 2.5) over25 += p;
    if (h > 0 && a > 0) btts += p;
  }
  return { lh, la, home, draw, away, over25, btts };
}

// A ket forras maskepp irja a csapatneveket. Ami nem illeszkedik, az az
// unmatched listaba kerul es megjelenik a jelentesben - nem tunik el csendben.
const ALIAS = {
  'manchester united': 'Man United', 'manchester city': 'Man City',
  'newcastle united': 'Newcastle', 'tottenham hotspur': 'Tottenham',
  'wolverhampton wanderers': 'Wolves', 'nottingham forest': "Nott'm Forest",
  'brighton and hove albion': 'Brighton', 'brighton & hove albion': 'Brighton',
  'west ham united': 'West Ham', 'leeds united': 'Leeds',
  'leicester city': 'Leicester', 'ipswich town': 'Ipswich',
  'sheffield united': 'Sheffield United', 'luton town': 'Luton',
  'afc bournemouth': 'Bournemouth', 'crystal palace': 'Crystal Palace',
  'atletico madrid': 'Ath Madrid', 'athletic bilbao': 'Ath Bilbao',
  'real sociedad': 'Sociedad', 'real betis': 'Betis',
  'celta vigo': 'Celta', 'rayo vallecano': 'Vallecano',
  'deportivo alaves': 'Alaves', 'real valladolid': 'Valladolid',
  'racing santander': 'Santander', 'real madrid': 'Real Madrid',
  'fc barcelona': 'Barcelona', 'barcelona': 'Barcelona',
  'bayern munich': 'Bayern Munich', 'bayern munchen': 'Bayern Munich',
  'borussia dortmund': 'Dortmund', 'borussia monchengladbach': "M'gladbach",
  'bayer leverkusen': 'Leverkusen', 'eintracht frankfurt': 'Ein Frankfurt',
  'vfb stuttgart': 'Stuttgart', 'vfl wolfsburg': 'Wolfsburg',
  'werder bremen': 'Werder Bremen', 'fc koln': 'FC Koln', '1 fc koln': 'FC Koln',
  'rb leipzig': 'RB Leipzig', 'sc freiburg': 'Freiburg', 'fc augsburg': 'Augsburg',
  'mainz 05': 'Mainz', 'fsv mainz 05': 'Mainz', 'tsg hoffenheim': 'Hoffenheim',
  'inter milan': 'Inter', 'ac milan': 'Milan', 'as roma': 'Roma',
  'ss lazio': 'Lazio', 'ssc napoli': 'Napoli',
  'atalanta bc': 'Atalanta', 'acf fiorentina': 'Fiorentina',
  'hellas verona': 'Verona', 'us lecce': 'Lecce', 'torino fc': 'Torino',
  'paris saint germain': 'Paris SG', 'paris saintgermain': 'Paris SG',
  'olympique marseille': 'Marseille', 'olympique lyonnais': 'Lyon',
  'as monaco': 'Monaco', 'lille osc': 'Lille', 'stade rennais': 'Rennes',
  'ogc nice': 'Nice', 'rc lens': 'Lens', 'fc nantes': 'Nantes',
};
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();

function findTeam(ratings, league, apiName) {
  const direct = ratings[league + '|' + apiName];
  if (direct) return direct;
  const n = norm(apiName);
  const aliased = ALIAS[n];
  if (aliased && ratings[league + '|' + aliased]) return ratings[league + '|' + aliased];
  const keys = Object.keys(ratings).filter(k => k.startsWith(league + '|'));
  for (const k of keys) if (norm(k.slice(league.length + 1)) === n) return ratings[k];
  for (const k of keys) {
    const nt = norm(k.slice(league.length + 1));
    if (nt.length >= 4 && (n.includes(nt) || nt.includes(n))) return ratings[k];
  }
  return null;
}

// --- feldolgozas ---
const legs = [];
const unmatched = [], tooThin = [], oddsErrors = [];
let model = null, eventsSeen = 0, creditsLeft = null;
const marketsSeen = {};

for (const item of $input.all()) {
  const j = item.json;
  if (!model && j._model) model = j._model;
  const mdl = j._model || model;
  if (!mdl) continue;
  const cfg = mdl.config || {};
  const haircut = cfg.tippmixHaircut !== undefined ? cfg.tippmixHaircut : 0.045;
  const league = j.code, leagueName = j.name;

  // Kredit-fogyas a valasz fejlecebol. A The Odds API koltsege piacok x regiok,
  // nem keresenkent 1 - ezert kell figyelni.
  const hdr = j.headers || {};
  if (hdr['x-requests-remaining'] !== undefined) creditsLeft = Number(hdr['x-requests-remaining']);

  const status = j.statusCode;
  const body = j.body !== undefined ? j.body : j;
  if (status && status !== 200) { oddsErrors.push(leagueName + ': HTTP ' + status); continue; }
  if (!Array.isArray(body)) continue;
  const meta = (mdl.leagueMeta || {})[league];
  if (!meta) continue;

  for (const ev of body) {
    eventsSeen++;
    if (!ev.bookmakers || ev.bookmakers.length < 3) continue;
    const hoursAhead = (new Date(ev.commence_time) - new Date()) / 3600000;
    if (hoursAhead < 0 || hoursAhead > (cfg.maxHoursAhead || 96)) continue;

    const hr = findTeam(mdl.ratings, league, ev.home_team);
    const ar = findTeam(mdl.ratings, league, ev.away_team);
    if (!hr || !ar) {
      if (!hr) unmatched.push(leagueName + ': ' + ev.home_team);
      if (!ar) unmatched.push(leagueName + ': ' + ev.away_team);
      continue;
    }
    // Keves meccsu csapat (ujonc a szezon elejen): a rating megbizhatatlan.
    if (hr.matches < 8 || ar.matches < 8) {
      const thin = [];
      if (hr.matches < 8) thin.push(hr.team + ' (' + hr.matches + ')');
      if (ar.matches < 8) thin.push(ar.team + ' (' + ar.matches + ')');
      tooThin.push(leagueName + ': ' + ev.home_team + ' vs ' + ev.away_team + ' - ' + thin.join(', '));
      continue;
    }

    const pr = predict(hr, ar, meta.leagueAvg, meta.homeAdv);

    const q = {};
    const add = (key, price, book) => {
      const p = Number(price);
      if (!Number.isFinite(p) || p <= 1) return;
      (q[key] = q[key] || []).push({ price: p, book });
    };
    for (const bk of ev.bookmakers) {
      for (const mk of (bk.markets || [])) {
        marketsSeen[mk.key] = (marketsSeen[mk.key] || 0) + 1;
        for (const oc of (mk.outcomes || [])) {
          const bookName = bk.title || bk.key;
          if (mk.key === 'h2h') {
            if (oc.name === ev.home_team) add('h2h|home', oc.price, bookName);
            else if (oc.name === ev.away_team) add('h2h|away', oc.price, bookName);
            else if (String(oc.name).toLowerCase() === 'draw') add('h2h|draw', oc.price, bookName);
          } else if (mk.key === 'totals') {
            if (Number(oc.point) !== 2.5) continue;
            const nm = String(oc.name).toLowerCase();
            if (nm === 'over') add('totals|over25', oc.price, bookName);
            else if (nm === 'under') add('totals|under25', oc.price, bookName);
          } else if (mk.key === 'btts') {
            const nm = String(oc.name).toLowerCase();
            if (nm === 'yes') add('btts|btts_yes', oc.price, bookName);
            else if (nm === 'no') add('btts|btts_no', oc.price, bookName);
          }
        }
      }
    }

    // De-vigeles piaconkent kulon. Ha egy piac nincs meg (pl. a btts nem
    // elerheto ezen az instancian), az a piac egyszeruen kimarad.
    const devig = keys => {
      for (const k of keys) if (!(q[k] || []).length || q[k].length < 3) return null;
      const best = {}, avg = {};
      for (const k of keys) {
        const ps = q[k].map(x => x.price);
        best[k] = Math.max(...ps);
        avg[k] = ps.reduce((a, b) => a + b, 0) / ps.length;
      }
      const ipSum = keys.reduce((a, k) => a + 1 / best[k], 0);
      const probs = {};
      for (const k of keys) probs[k] = (1 / best[k]) / ipSum;
      return { best, avg, probs, marginPct: (ipSum - 1) * 100 };
    };

    const SPECS = [
      { keys: ['h2h|home', 'h2h|draw', 'h2h|away'],
        model: { 'h2h|home': pr.home, 'h2h|draw': pr.draw, 'h2h|away': pr.away },
        labels: { 'h2h|home': '1 (hazai)', 'h2h|draw': 'X (dontetlen)', 'h2h|away': '2 (vendeg)' } },
      { keys: ['totals|over25', 'totals|under25'],
        model: { 'totals|over25': pr.over25, 'totals|under25': 1 - pr.over25 },
        labels: { 'totals|over25': 'Over 2.5 gol', 'totals|under25': 'Under 2.5 gol' } },
      { keys: ['btts|btts_yes', 'btts|btts_no'],
        model: { 'btts|btts_yes': pr.btts, 'btts|btts_no': 1 - pr.btts },
        labels: { 'btts|btts_yes': 'Mindketto szorez', 'btts|btts_no': 'Nem szorez mindketto' } },
    ];

    for (const spec of SPECS) {
      const d = devig(spec.keys);
      if (!d) continue;
      for (const k of spec.keys) {
        const parts = k.split('|');
        const market = parts[0], selection = parts[1];
        const mp = spec.model[k], kp = d.probs[k];
        const diff = mp - kp;
        // A bizalom a modell es a piac EGYETERTESEBOL jon, nem az elteresebol.
        // Meres: ahol a modell sokkal tobbet lat, ott jellemzoen a modell teved.
        let confidence;
        if (Math.abs(diff) <= 0.03) confidence = 'MAGAS';
        else if (diff <= 0.08) confidence = 'KOZEPES';
        else confidence = 'ALACSONY';

        legs.push({
          leg_id: ev.id + '-' + market + '-' + selection,
          event_id: ev.id,
          match_name: ev.home_team + ' vs ' + ev.away_team,
          home_team: ev.home_team, away_team: ev.away_team,
          league: leagueName, kickoff: ev.commence_time,
          market: market, selection: selection, label: spec.labels[k],
          model_prob: Math.round(mp * 10000) / 10000,
          market_prob: Math.round(kp * 10000) / 10000,
          market_avg_odds: Math.round(d.avg[k] * 100) / 100,
          best_odds: Math.round(d.best[k] * 100) / 100,
          tippmix_odds: Math.round(d.avg[k] * (1 - haircut) * 100) / 100,
          confidence: confidence,
          news_flag: 'ok', news_note: '',
          created_at: new Date().toISOString(),
        });
      }
    }
  }
}

const summary = {
  _summary: true,
  events_seen: eventsSeen, legs_built: legs.length,
  unmatched: [...new Set(unmatched)], too_thin: [...new Set(tooThin)],
  odds_errors: oddsErrors, markets_seen: marketsSeen,
  credits_left: creditsLeft,
  model_matches: model ? model.total_matches : 0,
  model_teams: model ? model.teams_rated : 0,
  fetch_errors: model ? model.fetch_errors : [],
  config: model ? model.config : {},
};
if (!legs.length) return [{ json: summary }];
return [...legs.map(l => ({ json: l })), { json: summary }];

// A cikkek szurese azokra, amelyek a slate csapatait emlitik, majd EGY prompt.
// Egyetlen LLM hivas futasonkent — nem csapatonkent, hogy olcso maradjon.

const legs = $input.all().map(i => i.json).filter(l => l.leg_id);
const articles = (() => {
  try { return $('Parse Articles').first().json._articles || []; } catch (e) { return []; }
})();

// csapatnevek a slate-rol
const teams = new Set();
for (const l of legs) {
  if (l.home_team) teams.add(l.home_team);
  if (l.away_team) teams.add(l.away_team);
  if (!l.home_team && l.match_name) {
    const p = String(l.match_name).split(' vs ');
    if (p[0]) teams.add(p[0].trim());
    if (p[1]) teams.add(p[1].trim());
  }
}
const teamList = [...teams];

// egyszeru nevegyezes: a cikk cime vagy leadje tartalmazza a csapatnevet
const norm = s => String(s).toLowerCase();
const matched = [];
for (const a of articles) {
  const hay = norm(a.title + ' ' + a.description);
  const hits = teamList.filter(t => {
    const n = norm(t);
    if (n.length < 4) return false;
    return hay.includes(n);
  });
  if (hits.length) matched.push({ ...a, teams: hits });
}

// max 40 cikk, hogy a prompt kezelheto maradjon
const use = matched.slice(0, 40);

const payload = use.map((a, i) =>
  (i + 1) + '. [' + a.teams.join(', ') + '] ' + a.title + (a.description ? ' — ' + a.description : '')
).join('\n');

return [{ json: {
  has_news: use.length > 0,
  article_count: use.length,
  total_articles: articles.length,
  teams_on_slate: teamList.length,
  news_payload: payload,
  team_list: teamList.join(', '),
}}];

