// Az LLM valaszanak alkalmazasa a labakra.
//
// FONTOS TERVEZESI DONTES: a hir NEM modositja a valoszinuseget.
// A hir->valoszinuseg konverziora nincs validalt meresunk, es egy kitalalt
// szorzo elrontana a kalibraciot, ami a modell egyetlen bizonyitott erenye.
// Ehelyett a hir KIZAR (veto) vagy megjelol (warn).

const legs = (() => {
  try { return $('Split Legs').all().map(i => i.json).filter(l => l.leg_id); } catch (e) { return []; }
})();

// Az LLM valasza. Vedekezo parse: ha barmi elromlik, a slate hir nelkul megy tovabb.
let signals = [];
let llmError = null;
try {
  const items = $input.all().map(i => i.json);
  const raw = items.map(x => x.text || x.output || x.response || x.data || '').filter(Boolean).join('\n');
  if (raw) {
    const m = raw.match(/\[[\s\S]*\]/);
    if (m) {
      const parsed = JSON.parse(m[0]);
      if (Array.isArray(parsed)) signals = parsed;
    }
  }
} catch (e) {
  llmError = String(e.message || e).slice(0, 120);
}

const norm = s => String(s || '').toLowerCase().trim();
const byTeam = {};
for (const s of signals) {
  const t = norm(s.team);
  if (!t) continue;
  const sev = Number(s.severity);
  byTeam[t] = {
    impact: norm(s.impact),
    severity: Number.isFinite(sev) ? sev : 0,
    reason: String(s.reason || '').slice(0, 120),
  };
}

// Melyik csapat MELLETT szol egy lab? Csak azokra alkalmazunk vetot.
const backedTeams = leg => {
  const parts = String(leg.match_name || '').split(' vs ');
  const home = leg.home_team || (parts[0] || '').trim();
  const away = leg.away_team || (parts[1] || '').trim();
  if (leg.market === 'h2h') {
    if (leg.selection === 'home') return [home];
    if (leg.selection === 'away') return [away];
    return [];                       // dontetlen: egyik csapat mellett sem szol
  }
  return [];                         // totals / btts: nem csapat-fuggo iranyban
};

let vetoed = 0, warned = 0;
const out = legs.map(l => {
  const backed = backedTeams(l);
  let flag = 'ok', note = '';
  for (const t of backed) {
    const sig = byTeam[norm(t)];
    if (!sig || sig.impact !== 'negative') continue;
    if (sig.severity >= 2) { flag = 'veto'; note = t + ': ' + sig.reason; break; }
    if (sig.severity === 1 && flag === 'ok') { flag = 'warn'; note = t + ': ' + sig.reason; }
  }
  if (flag === 'veto') vetoed++; else if (flag === 'warn') warned++;
  return { json: { ...l, news_flag: flag, news_note: note } };
});

const meta = {
  _news_meta: true,
  signals_found: signals.length,
  vetoed, warned,
  llm_error: llmError,
};
if (!out.length) return [{ json: meta }];
return [...out, { json: meta }];

// Pontosan a bet_slate oszlopaira szukites. A meta itemet (_news_meta) kiszurjuk.
const COLS = ['leg_id','event_id','match_name','league','kickoff','market','selection',
  'label','model_prob','market_prob','tippmix_odds','market_avg_odds','best_odds',
  'confidence','news_flag','news_note','created_at'];
return $input.all()
  .filter(i => i.json && i.json.leg_id)
  .map(i => {
    const o = {};
    for (const c of COLS) o[c] = i.json[c] !== undefined && i.json[c] !== null ? i.json[c] : (c === 'news_note' ? '' : null);
    return { json: o };
  });

// Jelentes. Minden adatot $() hivatkozassal olvas, ezert a lanc vegen allhat.
const grab = (node, fn, dflt) => { try { return fn($(node)); } catch (e) { return dflt; } };
const s = grab('Generate Legs', n => n.all().map(i => i.json).find(x => x._summary), {}) || {};
const newsMeta = grab('Apply News', n => n.all().map(i => i.json).find(x => x._news_meta), {}) || {};
const prompt = grab('Build News Prompt', n => n.first().json, {}) || {};
const articles = grab('Parse Articles', n => n.first().json, {}) || {};
const written = grab('Prepare Rows', n => n.all().length, null);

const mk = s.markets_seen || {};
const L = [];
L.push('📋 SLATE FRISSITVE');
L.push('');
L.push('Labak: ' + (s.legs_built || 0) + (written !== null ? ' (kiirva: ' + written + ')' : ''));
L.push('Meccsek atnezve: ' + (s.events_seen || 0));
L.push('Modell: ' + (s.model_matches || 0) + ' meccs, ' + (s.model_teams || 0) + ' csapat');
L.push('');
L.push('Piacok: h2h ' + (mk.h2h || 0) + ' · totals ' + (mk.totals || 0) + ' · btts ' + (mk.btts || 0));
if (!mk.btts) L.push('ℹ️ A btts piac nem jott vissza — a szelveny a masik ket piacbol epul.');
L.push('');
L.push('Hirek: ' + (articles._articles ? articles._articles.length : 0) + ' cikk, '
  + (prompt.article_count || 0) + ' illeszkedo');
if (newsMeta.signals_found !== undefined) {
  L.push('Hir-jelzes: ' + newsMeta.signals_found + ' · kizarva: ' + (newsMeta.vetoed || 0)
    + ' · megjelolve: ' + (newsMeta.warned || 0));
}
if (newsMeta.llm_error) L.push('⚠️ LLM parse hiba: ' + newsMeta.llm_error);
if (s.credits_left !== null && s.credits_left !== undefined) {
  L.push('');
  L.push('Odds API kredit maradt: ' + s.credits_left);
  if (s.credits_left < 60) L.push('⚠️ Fogy a havi keret.');
}

const probs = [];
if ((s.too_thin || []).length) probs.push('ℹ️ Keves adat miatt kihagyva (' + s.too_thin.length + '):\n' + s.too_thin.slice(0, 4).join('\n'));
if ((s.unmatched || []).length) probs.push('⚠️ Parositatlan csapatok (' + s.unmatched.length + '):\n' + s.unmatched.slice(0, 5).join('\n'));
if ((s.odds_errors || []).length) probs.push('⚠️ Odds hibak:\n' + s.odds_errors.slice(0, 3).join('\n'));
if ((s.fetch_errors || []).length) probs.push('⚠️ Adatletoltes:\n' + s.fetch_errors.slice(0, 3).join('\n'));
if ((articles._news_errors || []).length) probs.push('⚠️ Hir-letoltes:\n' + articles._news_errors.slice(0, 3).join('\n'));

let msg = L.join('\n');
if (probs.length) msg += '\n\n' + probs.join('\n\n');
if (!s.legs_built) msg += '\n\n❗ Nincs lab a slate-en. A /szelveny parancs addig nem tud dolgozni.';

return [{ json: { message: msg, legs: s.legs_built || 0, written } }];
